export function parseCsv(text) {
  if (text === '') return [];

  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let i = 0;

  const endField = () => {
    row.push(field);
    field = '';
  };
  const endRow = () => {
    endField();
    rows.push(row);
    row = [];
  };

  while (i < text.length) {
    const ch = text[i];

    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        inQuotes = false;
        i += 1;
        continue;
      }
      field += ch;
      i += 1;
      continue;
    }

    if (ch === '"' && field === '') {
      inQuotes = true;
      i += 1;
      continue;
    }
    if (ch === ',') {
      endField();
      i += 1;
      continue;
    }
    if (ch === '\r' && text[i + 1] === '\n') {
      endRow();
      i += 2;
      continue;
    }
    if (ch === '\n' || ch === '\r') {
      endRow();
      i += 1;
      continue;
    }
    field += ch;
    i += 1;
  }

  // A final line break does not add an empty row.
  const endsWithBreak =
    text.endsWith('\n') || text.endsWith('\r');
  if (!endsWithBreak) endRow();

  return rows;
}

export function toObjects(rows) {
  if (rows.length === 0) return [];
  const header = rows[0];
  return rows.slice(1).map((row) => {
    const record = {};
    for (let i = 0; i < header.length; i += 1) {
      record[header[i]] = i < row.length ? row[i] : '';
    }
    return record;
  });
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { parseCsv, toObjects } from '../src/csv.js';

test('empty text gives no rows', () => {
  assert.deepEqual(parseCsv(''), []);
});

test('plain rows split on commas', () => {
  assert.deepEqual(parseCsv('a,b\nc,d'), [
    ['a', 'b'],
    ['c', 'd'],
  ]);
});

test('a trailing line break does not add an empty row', () => {
  assert.deepEqual(parseCsv('a,b\n'), [['a', 'b']]);
  assert.deepEqual(parseCsv('a,b\r\n'), [['a', 'b']]);
});

test('CRLF line endings are handled', () => {
  assert.deepEqual(parseCsv('a,b\r\nc,d\r\n'), [
    ['a', 'b'],
    ['c', 'd'],
  ]);
});

test('quoted fields may contain commas', () => {
  assert.deepEqual(parseCsv('"a,b",c'), [['a,b', 'c']]);
});

test('quoted fields may contain line breaks', () => {
  assert.deepEqual(parseCsv('"a\nb",c'), [['a\nb', 'c']]);
  assert.deepEqual(parseCsv('"a\r\nb",c'), [['a\r\nb', 'c']]);
});

test('doubled double quotes inside a quoted field mean one quote', () => {
  assert.deepEqual(parseCsv('"say ""hi""",x'), [['say "hi"', 'x']]);
  assert.deepEqual(parseCsv('""""'), [['"']]);
});

test('empty fields are preserved', () => {
  assert.deepEqual(parseCsv('a,,c'), [['a', '', 'c']]);
  assert.deepEqual(parseCsv(','), [['', '']]);
});

test('toObjects keys rows by the header', () => {
  assert.deepEqual(toObjects([['name', 'age'], ['Ada', '36'], ['Bob', '41']]), [
    { name: 'Ada', age: '36' },
    { name: 'Bob', age: '41' },
  ]);
});

test('toObjects gives short rows empty strings for missing columns', () => {
  assert.deepEqual(toObjects([['a', 'b', 'c'], ['1']]), [{ a: '1', b: '', c: '' }]);
  assert.deepEqual(toObjects([['a', 'b'], ['1', '2', '3']]), [{ a: '1', b: '2' }]);
});

test('toObjects with only a header gives no records', () => {
  assert.deepEqual(toObjects([['a', 'b']]), []);
  assert.deepEqual(toObjects([]), []);
});
